import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"VPS 控制台操作指南","description":"","frontmatter":{"title":"VPS 控制台操作指南"},"headers":[],"relativePath":"ops-knowledge-base/vps/console-guide.md","filePath":"ops-knowledge-base/vps/console-guide.md","lastUpdated":1794309341000}'),o={name:"ops-knowledge-base/vps/console-guide.md"};function p(t,a,h,s,n,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍 VPS 控制台各功能模块及基本操作，帮助客户快速熟悉后台管理页面。</p><p>对于升级/降级、弹性 IP、独立云盘、安全组、快照等功能，本文仅作简单介绍，详细操作请参考对应的知识库文档。</p><p><strong>适用产品：</strong></p><ul><li>VPS（Virtual Private Server）</li></ul><hr><h2 id="一、进入-vps-控制台" tabindex="-1">一、进入 VPS 控制台 <a class="header-anchor" href="#一、进入-vps-控制台" aria-label="Permalink to &quot;一、进入 VPS 控制台&quot;">​</a></h2><p>操作步骤：</p><ol><li>登录 Raksmart 客户后台。</li><li>进入 <strong>产品管理 → VPS</strong>。</li><li>选择需要管理的 VPS。</li><li>点击进入产品详情页面。</li></ol><p>进入后，可查看服务器基本信息，包括：</p><ul><li>区域</li><li>CPU</li><li>内存</li><li>操作系统</li><li>IP 地址</li><li>登录密码（支持复制）</li><li>VNC</li><li>升级/降级</li></ul><hr><h2 id="二、服务器基本信息" tabindex="-1">二、服务器基本信息 <a class="header-anchor" href="#二、服务器基本信息" aria-label="Permalink to &quot;二、服务器基本信息&quot;">​</a></h2><p>页面左侧显示当前 VPS 的基础信息，包括：</p><ul><li>区域（Region）</li><li>CPU</li><li>内存</li><li>系统盘规格</li><li>用户名</li><li>SSH 端口（Linux）</li><li>备注（如已设置）</li></ul><p>客户可通过此页面快速查看服务器当前配置信息及登录信息。</p><hr><h2 id="三、电源管理" tabindex="-1">三、电源管理 <a class="header-anchor" href="#三、电源管理" aria-label="Permalink to &quot;三、电源管理&quot;">​</a></h2><p>页面左侧提供服务器常用的电源管理功能。</p><p>包括：</p><ul><li>开机</li><li>关机</li><li>重启</li><li>硬关机</li><li>硬重启</li><li>重置密码</li><li>重装系统</li><li>救援系统（Rescue）</li></ul><p>各功能说明如下：</p><h3 id="开机" tabindex="-1">开机 <a class="header-anchor" href="#开机" aria-label="Permalink to &quot;开机&quot;">​</a></h3><p>用于启动已关机的 VPS。</p><p>适用于：</p><ul><li>VPS 已关闭；</li><li>完成维护后恢复运行。</li></ul><hr><h3 id="关机" tabindex="-1">关机 <a class="header-anchor" href="#关机" aria-label="Permalink to &quot;关机&quot;">​</a></h3><p>用于正常关闭服务器操作系统。</p><p>建议在维护或停止业务前使用。</p><hr><h3 id="重启" tabindex="-1">重启 <a class="header-anchor" href="#重启" aria-label="Permalink to &quot;重启&quot;">​</a></h3><p>用于正常重新启动服务器。</p><p>适用于：</p><ul><li>系统更新完成；</li><li>修改配置后使配置生效；</li><li>系统异常需要重新启动。</li></ul><hr><h3 id="硬关机" tabindex="-1">硬关机 <a class="header-anchor" href="#硬关机" aria-label="Permalink to &quot;硬关机&quot;">​</a></h3><p>直接关闭服务器电源。</p><p>说明：</p><p>硬关机不会通知操作系统正常退出，仅建议在服务器无法正常关机时使用。</p><hr><h3 id="硬重启" tabindex="-1">硬重启 <a class="header-anchor" href="#硬重启" aria-label="Permalink to &quot;硬重启&quot;">​</a></h3><p>直接重新启动服务器。</p><p>说明：</p><p>当服务器无法正常响应时，可使用硬重启进行恢复。</p><p>建议仅在普通重启无法执行时使用。</p><hr><h3 id="重置密码" tabindex="-1">重置密码 <a class="header-anchor" href="#重置密码" aria-label="Permalink to &quot;重置密码&quot;">​</a></h3><p>用于重新设置服务器登录密码。</p><p>适用于：</p><ul><li>忘记登录密码；</li><li>首次修改默认密码。</li></ul><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/baremetal/password-change-reset-guide.html">裸机云 密码修改与重置指南</a>》</strong></p><hr><h3 id="重装系统" tabindex="-1">重装系统 <a class="header-anchor" href="#重装系统" aria-label="Permalink to &quot;重装系统&quot;">​</a></h3><p>用于重新安装 VPS 操作系统。</p><p>支持安装 Linux、Windows 等系统（具体以后台显示为准）。</p><p>说明：</p><p>重装系统将清空系统盘中的数据，请提前做好重要数据备份。</p><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/baremetal/reinstall-os-guide.html">裸机云 重装系统指南</a>》</strong></p><hr><h3 id="救援系统-rescue" tabindex="-1">救援系统（Rescue） <a class="header-anchor" href="#救援系统-rescue" aria-label="Permalink to &quot;救援系统（Rescue）&quot;">​</a></h3><p>当服务器无法正常启动时，可进入 Rescue 模式进行系统修复或数据恢复。</p><p>常见使用场景：</p><ul><li>系统无法启动；</li><li>修复文件系统；</li><li>修复启动配置；</li><li>数据恢复。</li></ul><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/baremetal/rescue-mode-guide.html">裸机云 救援系统（Rescue）使用指南</a>》</strong></p><hr><h2 id="四、vnc-控制台" tabindex="-1">四、VNC 控制台 <a class="header-anchor" href="#四、vnc-控制台" aria-label="Permalink to &quot;四、VNC 控制台&quot;">​</a></h2><p>点击页面顶部 <strong>VNC</strong> 按钮，可打开服务器控制台。</p><p>即使服务器网络异常，仍可通过 VNC 登录服务器。</p><p>常见使用场景：</p><ul><li>SSH 无法连接；</li><li>RDP 无法连接；</li><li>修改系统密码；</li><li>查看系统启动过程；</li><li>系统维护。</li></ul><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/baremetal/vnc-console-guide.html">裸机云 VNC 控制台使用指南</a>》</strong></p><hr><h2 id="五、升级-降级" tabindex="-1">五、升级/降级 <a class="header-anchor" href="#五、升级-降级" aria-label="Permalink to &quot;五、升级/降级&quot;">​</a></h2><p>点击页面顶部 <strong>升级/降级</strong> 按钮，可根据业务需求调整服务器配置。</p><p>支持调整的资源以后台显示为准，例如：</p><ul><li>CPU</li><li>内存</li><li>带宽</li><li>流量</li></ul><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/baremetal/upgrade-downgrade-guide.html">裸机云 升级/降级操作指南</a>》</strong></p><hr><h2 id="六、图表" tabindex="-1">六、图表 <a class="header-anchor" href="#六、图表" aria-label="Permalink to &quot;六、图表&quot;">​</a></h2><p>&quot;图表&quot;页面用于查看服务器实时资源使用情况。</p><p>支持查看：</p><ul><li>CPU 使用率</li><li>硬盘 IO</li><li>内存使用量</li><li>网卡流量</li></ul><p>帮助客户了解服务器运行状态及资源使用情况。</p><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/vps/monitoring-guide.html">VPS 监控功能说明</a>》</strong></p><hr><h2 id="七、用量" tabindex="-1">七、用量 <a class="header-anchor" href="#七、用量" aria-label="Permalink to &quot;七、用量&quot;">​</a></h2><p>&quot;用量&quot;页面用于查看 VPS 的网络流量统计。</p><p>支持：</p><ul><li>查看历史流量；</li><li>自定义日期范围查询；</li><li>统计指定时间段内的网络使用情况。</li></ul><p>可用于分析业务流量及网络使用趋势。</p><hr><h2 id="八、弹性-ip" tabindex="-1">八、弹性 IP <a class="header-anchor" href="#八、弹性-ip" aria-label="Permalink to &quot;八、弹性 IP&quot;">​</a></h2><p>&quot;弹性 IP&quot;页面用于管理 VPS 已购买的弹性 IP。</p><p>支持：</p><ul><li>查看弹性 IP；</li><li>绑定弹性 IP；</li><li>解绑弹性 IP。</li></ul><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/vps/elastic-ip-guide.html">VPS 弹性 IP 使用指南</a>》</strong></p><hr><h2 id="九、独立云盘" tabindex="-1">九、独立云盘 <a class="header-anchor" href="#九、独立云盘" aria-label="Permalink to &quot;九、独立云盘&quot;">​</a></h2><p>&quot;独立云盘&quot;页面用于管理已购买的独立云盘。</p><p>支持：</p><ul><li>查看云盘；</li><li>挂载云盘；</li><li>卸载云盘。</li></ul><p>说明：</p><p>后台完成挂载后，还需登录系统完成磁盘初始化及挂载操作。</p><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/vps/cloud-disk-guide.html">VPS 独立云盘使用指南</a>》</strong></p><hr><h2 id="十、安全组" tabindex="-1">十、安全组 <a class="header-anchor" href="#十、安全组" aria-label="Permalink to &quot;十、安全组&quot;">​</a></h2><p>&quot;安全组&quot;页面用于管理服务器网络访问策略。</p><p>支持：</p><ul><li>创建安全组；</li><li>管理安全组规则；</li><li>绑定安全组；</li><li>解绑安全组。</li></ul><p>可用于控制服务器允许访问的端口及网络策略。</p><p>详细操作请参考：</p><p><strong>《<a href="/ops-knowledge-base/vps/security-group-guide.html">VPS 安全组使用指南</a>》</strong></p><hr><h2 id="十一、快照" tabindex="-1">十一、快照 <a class="header-anchor" href="#十一、快照" aria-label="Permalink to &quot;十一、快照&quot;">​</a></h2><p>&quot;快照&quot;页面用于保存服务器当前状态，方便后续恢复。</p><p>建议在以下场景创建快照：</p><ul><li>系统升级前；</li><li>安装软件前；</li><li>修改重要配置前；</li><li>业务上线前。</li></ul><p>说明：</p><p>快照可用于快速恢复服务器状态，但不能替代数据备份。</p><p>详细操作请参考：</p><p><strong>《VPS 快照使用指南》</strong></p><hr><h2 id="十二、常见问题" tabindex="-1">十二、常见问题 <a class="header-anchor" href="#十二、常见问题" aria-label="Permalink to &quot;十二、常见问题&quot;">​</a></h2><h3 id="q1-为什么点击关机后服务器没有立即关闭" tabindex="-1">Q1：为什么点击关机后服务器没有立即关闭？ <a class="header-anchor" href="#q1-为什么点击关机后服务器没有立即关闭" aria-label="Permalink to &quot;Q1：为什么点击关机后服务器没有立即关闭？&quot;">​</a></h3><p>服务器执行的是正常关机流程，具体耗时取决于操作系统及当前运行的服务，请耐心等待并刷新服务器状态。</p><hr><h3 id="q2-什么时候需要使用硬关机或硬重启" tabindex="-1">Q2：什么时候需要使用硬关机或硬重启？ <a class="header-anchor" href="#q2-什么时候需要使用硬关机或硬重启" aria-label="Permalink to &quot;Q2：什么时候需要使用硬关机或硬重启？&quot;">​</a></h3><p>仅建议在服务器无响应、无法正常执行关机或重启操作时使用。</p><p>正常情况下，请优先使用&quot;关机&quot;或&quot;重启&quot;功能。</p><hr><h3 id="q3-重装系统会删除数据吗" tabindex="-1">Q3：重装系统会删除数据吗？ <a class="header-anchor" href="#q3-重装系统会删除数据吗" aria-label="Permalink to &quot;Q3：重装系统会删除数据吗？&quot;">​</a></h3><p>会。</p><p>重装系统将清空系统盘中的所有数据，请提前做好数据备份。</p><hr><h3 id="q4-vnc-与-ssh-或-windows-rdp-有什么区别" tabindex="-1">Q4：VNC 与 SSH（或 Windows RDP）有什么区别？ <a class="header-anchor" href="#q4-vnc-与-ssh-或-windows-rdp-有什么区别" aria-label="Permalink to &quot;Q4：VNC 与 SSH（或 Windows RDP）有什么区别？&quot;">​</a></h3><p>SSH 和 RDP 属于网络远程登录方式，而 VNC 为服务器控制台连接。</p><p>即使服务器网络异常、SSH 或 RDP 无法连接，通常仍可通过 VNC 登录服务器进行管理。</p><hr><h3 id="q5-为什么图表或用量没有数据显示" tabindex="-1">Q5：为什么图表或用量没有数据显示？ <a class="header-anchor" href="#q5-为什么图表或用量没有数据显示" aria-label="Permalink to &quot;Q5：为什么图表或用量没有数据显示？&quot;">​</a></h3><p>如果服务器刚创建、刚开机或刚恢复运行，监控数据可能需要一定时间进行采集。</p><p>建议稍后刷新页面再次查看。</p><hr>',151)])])}const q=l(o,[["render",p]]);export{c as __pageData,q as default};
